<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {RouterLink} from 'vue-router'
import {onAuthStateChanged} from 'firebase/auth'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {readStagingSession,stagingSession} from '../integrations/firebase/stagingSession'
import {isLiveMode} from '../integrations/firebase/stagingConfig'
import {workReport,type WorkReport} from '../integrations/firebase/workAttendance'
import {pilotAvailable} from '../features/work/gpsPilot'
import {dayState,dayTitle,duration,monthNow,monthTitle,partState,rangeLabel,siteName} from '../features/work/reportFormat'
import LionIcon from '../components/LionIcon.vue'
const month=ref(monthNow()),r=ref<WorkReport|null>(null),busy=ref(false),error=ref(''),notice=ref(''),notEnabled=ref(false),exporting=ref(false),files=ref<File[]>([]),expanded=ref<string[]>([])
const scope=computed(()=>`${stagingSession.value?.uid||''}:${stagingSession.value?.gymId||''}:${stagingSession.value?.role||''}`)
let alive=true,seq=0;const same=(s:string)=>alive&&scope.value===s&&getStagingClients().auth.currentUser?.uid===stagingSession.value?.uid&&pilotAvailable(stagingSession.value)
function reset(){seq++;r.value=null;files.value=[];expanded.value=[];busy.value=false;exporting.value=false;error.value='';notice.value='';notEnabled.value=false}
watch(scope,()=>{reset();if(alive&&pilotAvailable(stagingSession.value))void load()})
async function load(){const request=++seq;r.value=null;files.value=[];expanded.value=[];busy.value=true;error.value='';notice.value='';notEnabled.value=false;try{if(!isLiveMode())throw new Error('LionFit Work non disponibile.');const s=await readStagingSession();if(!alive||request!==seq)return;if(!pilotAvailable(s))throw new Error('Report riservato al personale autorizzato.');const key=scope.value,result=await workReport(s.uid,month.value);if(request!==seq||!same(key))return;if(!result.enabled){notEnabled.value=true;return}r.value=result}catch(e){if(alive&&request===seq)error.value=e instanceof Error?e.message:'Lettura non riuscita.'}finally{if(alive&&request===seq)busy.value=false}}
function move(delta:number){const [y,m]=month.value.split('-').map(Number),next=new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);if(next<'2000-01'||next>monthNow())return;month.value=next;void load()}
function choose(event:Event){const v=(event.target as HTMLInputElement).value;if(/^20\d\d-(0[1-9]|1[0-2])$/.test(v)&&v<=monthNow()){month.value=v;void load()}else (event.target as HTMLInputElement).value=month.value}
function toggle(date:string){expanded.value=expanded.value.includes(date)?expanded.value.filter(v=>v!==date):[...expanded.value,date]}
async function prepare(kind:'pdf'|'xlsx'){if(!r.value||busy.value||exporting.value)return;const key=scope.value,source=r.value,request=seq;exporting.value=true;notice.value='';error.value='';try{const {makeReportFile}=await import('../features/work/reportExport');const f=await makeReportFile(source,kind);if(!same(key)||request!==seq||r.value!==source)return;files.value=[...files.value.filter(v=>v.name!==f.name),f];notice.value='File pronto: scaricalo o condividilo qui sotto.'}catch(e){if(same(key)&&request===seq)error.value=e instanceof Error?e.message:'Esportazione non riuscita.'}finally{if(alive&&request===seq)exporting.value=false}}
function download(f:File){if(!same(scope.value)||!files.value.includes(f))return;const url=URL.createObjectURL(f),a=document.createElement('a');a.href=url;a.download=f.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function shareAvailable(f:File){try{return typeof navigator.share==='function'&&typeof navigator.canShare==='function'&&navigator.canShare({files:[f]})}catch{return false}}
async function share(f:File){if(!same(scope.value)||!files.value.includes(f)||!shareAvailable(f))return;const key=scope.value;try{await navigator.share({files:[f],title:'LionFit Work · '+monthTitle(month.value)})}catch(e){if(same(key)&&!(e instanceof DOMException&&e.name==='AbortError'))notice.value='Condivisione non disponibile: scarica il file e allegalo alla tua email.'}}
let stopAuth:(()=>void)|undefined
onMounted(()=>{if(isLiveMode())stopAuth=onAuthStateChanged(getStagingClients().auth,u=>{if(u?.uid!==stagingSession.value?.uid)reset()});void load()});onUnmounted(()=>{alive=false;stopAuth?.();reset()})
</script>
<template>
 <section class="work-report" aria-label="Report lavorativi">
  <div class="wr-head"><RouterLink to="/impostazioni" class="wr-back"><LionIcon name="back" :size="18"/> Impostazioni</RouterLink><h1>Report lavorativi</h1><span>Storico personale · LionFit Work</span></div>
  <section class="wr-month" aria-label="Seleziona mese"><button type="button" aria-label="Mese precedente" :disabled="busy||month<='2000-01'" @click="move(-1)">‹</button><div><strong>{{monthTitle(month)}}</strong><input type="month" :value="month" min="2000-01" :max="monthNow()" aria-label="Mese del report" :disabled="busy" @change="choose"/></div><button type="button" aria-label="Mese successivo" :disabled="busy||month>=monthNow()" @click="move(1)">›</button><button type="button" aria-label="Aggiorna report" :disabled="busy" @click="load"><LionIcon name="repeat"/></button></section>
  <p v-if="busy" role="status">Caricamento report…</p><p v-if="error" class="wr-alert" role="alert">{{error}}</p><p v-if="notEnabled" class="wr-panel">LionFit Work non è ancora configurato per la tua palestra. <RouterLink to="/impostazioni">Vai alle impostazioni</RouterLink></p>
  <template v-if="r">
   <section class="wr-panel wr-summary"><div class="wr-person"><img v-if="r.logo" :src="r.logo" alt="Logo palestra"/><div><b>{{r.gymName}}</b><small>{{r.person}}</small></div></div><small>Totale ore confermate</small><strong class="wr-total">{{duration(r.totalMs)}}</strong><div class="wr-sites" :style="{gridTemplateColumns:`repeat(${r.sites.length},minmax(0,1fr))`}"><div v-for="s in r.sites" :key="s.id"><span>{{s.name}}</span><b>{{duration(r.totals[s.id])}}</b></div></div><div class="wr-kpis"><span>Giorni lavorati <b>{{r.workedDays}}</b></span><span>Media/giorno <b>{{duration(r.workedDays?r.totalMs/r.workedDays:0)}}</b></span></div><p v-if="r.pendingMs||r.flaggedDays" class="wr-alert">{{r.flaggedDays}} giorni da verificare. Ore in attesa: {{duration(r.pendingMs)}} (escluse dal totale).</p></section>
   <section class="wr-panel wr-export"><h2>Esporta report</h2><div class="wr-actions"><button type="button" :disabled="exporting||busy" @click="prepare('pdf')"><LionIcon name="clipboard"/> PDF</button><button type="button" :disabled="exporting||busy" @click="prepare('xlsx')"><LionIcon name="save"/> Excel</button></div><p v-if="exporting" role="status">Preparazione file…</p><p v-if="notice" role="status">{{notice}}</p><div v-for="f in files" :key="f.name" class="wr-file"><strong>{{f.name}}</strong><div class="wr-actions"><button type="button" @click="download(f)">Scarica</button><button v-if="shareAvailable(f)" type="button" @click="share(f)">Condividi / email</button></div><small>Se necessario, scarica il file e allegalo manualmente alla tua email.</small></div></section>
   <section class="wr-panel wr-history"><h2>Dettaglio giornaliero</h2><p class="wr-note">Tocca un giorno per vedere tutti gli intervalli. Orari Europe/Rome; turni aperti non conteggiati.</p><div v-for="d in r.days" :key="d.date" class="wr-day"><button type="button" class="wr-dayhead" :aria-expanded="expanded.includes(d.date)" @click="toggle(d.date)"><div><b>{{dayTitle(d.date)}}</b><small>{{dayState(d)}}</small></div><div><strong>{{duration(d.totalMs)}}</strong><small v-if="d.pendingMs">+ {{duration(d.pendingMs)}} in attesa</small></div><span aria-hidden="true">{{expanded.includes(d.date)?'⌃':'⌄'}}</span></button><div v-if="expanded.includes(d.date)" class="wr-details"><div class="wr-site-line" v-for="s in r.sites" :key="s.id"><span>{{s.name}}</span><b>{{duration(d.bySite[s.id])}}</b></div><div v-for="(p,i) in d.parts" :key="i" class="wr-interval"><b>{{siteName(r,p.siteId)}}</b><span>{{rangeLabel(p,d)}}</span><small>{{duration(p.endMs-p.startMs)}} · {{partState(p)}}</small></div><small v-if="!d.parts.length">Nessun intervallo registrato.</small></div></div></section>
  </template>
 </section>
</template>
<style scoped>
.work-report{width:min(100%,880px);margin:0 auto;padding:12px 0 24px;display:grid;gap:14px;color:inherit;min-width:0}.wr-head h1{font-size:1.55rem;margin:10px 0 3px}.wr-head span,.work-report small,.wr-note{opacity:.78;font-size:.85rem}.wr-back{display:inline-flex;align-items:center;color:inherit;gap:5px;text-decoration:none}.wr-month,.wr-panel{border:1px solid var(--line,#354555);background:var(--panel,#17212c);border-radius:15px;padding:14px;min-width:0}.wr-month{display:flex;align-items:center;gap:8px}.wr-month>div{flex:1;text-align:center;min-width:0;display:grid;gap:4px}.wr-month strong{text-transform:capitalize}.wr-month input{font:inherit;color:inherit;background:transparent;border:1px solid var(--line,#53616c);padding:5px;border-radius:7px;max-width:100%;min-width:0;width:100%;color-scheme:dark}.work-report button{font:inherit;color:inherit;border:1px solid var(--line,#53616c);background:transparent;border-radius:10px;padding:10px;min-height:44px;cursor:pointer}.work-report button:disabled{opacity:.37;cursor:not-allowed}.wr-month>button{width:44px;flex:0 0 44px;font-size:1.4rem}.wr-panel h2{font-size:1.1rem;margin:0 0 12px}.wr-person{display:flex;gap:12px;align-items:center;margin-bottom:15px;text-align:left}.wr-person img{width:48px;height:48px;object-fit:contain;border-radius:8px}.wr-person div,.wr-summary,.wr-dayhead div,.wr-interval,.wr-file{display:grid;gap:5px}.wr-summary{text-align:center;gap:10px}.wr-total{font-size:2.3rem;color:#4ed894;font-variant-numeric:tabular-nums}.wr-sites,.wr-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.wr-sites>div{display:grid;gap:6px;background:#25845419;border:1px solid #38875c66;border-radius:10px;padding:12px 8px;overflow-wrap:anywhere}.wr-sites b{font-variant-numeric:tabular-nums;font-size:1.1rem}.wr-kpis{display:flex;justify-content:space-around;gap:8px;flex-wrap:wrap;font-size:.85rem}.wr-kpis b{display:block}.wr-alert{font-size:.87rem;margin:0;background:#d8912220;border:1px solid #b47e45;border-radius:8px;padding:10px}.wr-actions button{display:flex;justify-content:center;align-items:center;gap:6px;border-color:#328459;color:inherit;font-weight:700}.wr-file{border-top:1px solid var(--line,#42505b);margin-top:12px;padding-top:12px;overflow-wrap:anywhere}.wr-day{border-top:1px solid var(--line,#42505b)}.wr-dayhead{display:grid;grid-template-columns:minmax(0,1fr) auto 16px;align-items:center;gap:10px;text-align:left;width:100%;border:0!important;padding:12px 0!important}.wr-dayhead div:nth-child(2){text-align:right;font-variant-numeric:tabular-nums}.wr-details{border-top:1px solid var(--line,#42505b);padding:10px 0 13px;display:grid;gap:8px}.wr-site-line{display:flex;justify-content:space-between;gap:12px;overflow-wrap:anywhere}.wr-interval{background:#25845414;border-radius:8px;padding:9px;overflow-wrap:anywhere}.wr-note{margin:0 0 10px}.wr-panel a{color:inherit;text-decoration:underline}@media(max-width:380px){.wr-panel,.wr-month{padding:10px}.wr-month{gap:4px}.wr-month>button{width:38px;flex-basis:38px}.wr-sites b{font-size:1rem}.wr-total{font-size:2rem}}
</style>
